1172	\begin{definition}[Non-Degenerate Oracle Gap]
1173	$G_{\text{nd}} = \mathbb{E}[F_1^{\text{oracle}}(x) - F_1^{\text{greedy}}(x) \mid x \in \mathcal{D}_{\neg D}]$, where $\mathcal{D}_{\neg D}$ is the set of non-degenerate instances.
1174	\end{definition}
